import{_ as Q,b as t,d as r,aS as e,a}from"./chunks/framework.M2Whok06.js";const x=JSON.parse('{"title":"电学","description":"","frontmatter":{},"headers":[],"relativePath":"note/electricity/index.md","filePath":"note/electricity/index.md","lastUpdated":1745160117000}'),o={name:"note/electricity/index.md"},i=e('<h1 id="电学" tabindex="-1">电学 <a class="header-anchor" href="#电学" aria-label="Permalink to &quot;电学&quot;">​</a></h1><p>物理真奇妙，电学更奇妙，我对电有十万个为什么</p><h2 id="什么是电流" tabindex="-1">什么是电流 <a class="header-anchor" href="#什么是电流" aria-label="Permalink to &quot;什么是电流&quot;">​</a></h2><p>电流是电荷的流动，而金属导体中的电流通常是由自由电子的移动形成的。电池作为电源，提供电动势，驱动电子在闭合电路中流动。</p><p>那么问题来了，这些电子到底从哪里来的？</p><p>金属导体中的原子结构允许最外层的电子（自由电子）在原子之间自由移动。当没有电压时，这些电子的运动是随机的， 没有方向性，所以不会形成电流。当电池连接到电路时，电场在导线中建立，导致自由电子开始定向移动，形成电流。</p><p>电池的作用是维持这个电场。电池内部通过化学反应，在负极积累电子，正极则缺少电子。当电路闭合时，负极的电子被推斥进入导线，而正极则吸引导线中的电子，从而形成循环。</p><p>因此，电子实际上是从电池的负极出发，经过外部电路流向正极，而在电池内部，通过化学反应，电子又被运送回负极，维持电荷的平衡。</p><p>根据电荷守恒，在闭合电路中，电子是循环流动的，导线中的电子数量在动态中保持平衡，不会减少。</p><p><strong>电池的作用不是产生电子，而是通过化学能提供电势差，促使电子流动。所以，导线中的电子不会减少， 因为这是一个闭合的回路，电子只是在其中循环流动，而电池内部通过化学反应将电子从正极“搬运”回负极，维持电流的持续。</strong></p><h3 id="电流的定义" tabindex="-1">电流的定义 <a class="header-anchor" href="#电流的定义" aria-label="Permalink to &quot;电流的定义&quot;">​</a></h3>',11),n={xmlns:"http://www.w3.org/2000/svg",width:"6.942ex",height:"4.699ex",viewBox:"0 -1380 3068.6 2077","xmlns:xlink":"http://www.w3.org/1999/xlink","aria-hidden":"true",style:{}},T=e('<defs><path id="MJX-1-TEX-I-1D43C" d="M43 1Q26 1 26 10Q26 12 29 24Q34 43 39 45Q42 46 54 46H60Q120 46 136 53Q137 53 138 54Q143 56 149 77T198 273Q210 318 216 344Q286 624 286 626Q284 630 284 631Q274 637 213 637H193Q184 643 189 662Q193 677 195 680T209 683H213Q285 681 359 681Q481 681 487 683H497Q504 676 504 672T501 655T494 639Q491 637 471 637Q440 637 407 634Q393 631 388 623Q381 609 337 432Q326 385 315 341Q245 65 245 59Q245 52 255 50T307 46H339Q345 38 345 37T342 19Q338 6 332 0H316Q279 2 179 2Q143 2 113 2T65 2T43 1Z"></path><path id="MJX-1-TEX-N-3D" d="M56 347Q56 360 70 367H707Q722 359 722 347Q722 336 708 328L390 327H72Q56 332 56 347ZM56 153Q56 168 72 173H708Q722 163 722 153Q722 140 707 133H70Q56 140 56 153Z"></path><path id="MJX-1-TEX-I-1D444" d="M399 -80Q399 -47 400 -30T402 -11V-7L387 -11Q341 -22 303 -22Q208 -22 138 35T51 201Q50 209 50 244Q50 346 98 438T227 601Q351 704 476 704Q514 704 524 703Q621 689 680 617T740 435Q740 255 592 107Q529 47 461 16L444 8V3Q444 2 449 -24T470 -66T516 -82Q551 -82 583 -60T625 -3Q631 11 638 11Q647 11 649 2Q649 -6 639 -34T611 -100T557 -165T481 -194Q399 -194 399 -87V-80ZM636 468Q636 523 621 564T580 625T530 655T477 665Q429 665 379 640Q277 591 215 464T153 216Q153 110 207 59Q231 38 236 38V46Q236 86 269 120T347 155Q372 155 390 144T417 114T429 82T435 55L448 64Q512 108 557 185T619 334T636 468ZM314 18Q362 18 404 39L403 49Q399 104 366 115Q354 117 347 117Q344 117 341 117T337 118Q317 118 296 98T274 52Q274 18 314 18Z"></path><path id="MJX-1-TEX-I-1D461" d="M26 385Q19 392 19 395Q19 399 22 411T27 425Q29 430 36 430T87 431H140L159 511Q162 522 166 540T173 566T179 586T187 603T197 615T211 624T229 626Q247 625 254 615T261 596Q261 589 252 549T232 470L222 433Q222 431 272 431H323Q330 424 330 420Q330 398 317 385H210L174 240Q135 80 135 68Q135 26 162 26Q197 26 230 60T283 144Q285 150 288 151T303 153H307Q322 153 322 145Q322 142 319 133Q314 117 301 95T267 48T216 6T155 -11Q125 -11 98 4T59 56Q57 64 57 83V101L92 241Q127 382 128 383Q128 385 77 385H26Z"></path></defs><g stroke="currentColor" fill="currentColor" stroke-width="0" transform="matrix(1 0 0 -1 0 0)"><g data-mml-node="math"><g data-mml-node="mi"><use xlink:href="#MJX-1-TEX-I-1D43C"></use></g><g data-mml-node="mo" transform="translate(781.8, 0)"><use xlink:href="#MJX-1-TEX-N-3D"></use></g><g data-mml-node="mfrac" transform="translate(1837.6, 0)"><g data-mml-node="mi" transform="translate(220, 676)"><use xlink:href="#MJX-1-TEX-I-1D444"></use></g><g data-mml-node="mi" transform="translate(435, -686)"><use xlink:href="#MJX-1-TEX-I-1D461"></use></g><rect width="991" height="60" x="120" y="220"></rect></g></g></g>',2),s=[T],l=e('<ul><li>I：电流（单位：安培，符号 A）</li><li>Q：电荷量（单位：库仑，符号 C）</li><li>t：时间（单位：秒，符号 s）</li></ul><p>一秒内有6.2415093*10^18个元电荷（1库伦）通过横截面的电流就是1A</p><p>举例：若电流为 2A，则每秒有 2 库仑的电荷通过导线。</p><h3 id="库伦是什么" tabindex="-1">库伦是什么？ <a class="header-anchor" href="#库伦是什么" aria-label="Permalink to &quot;库伦是什么？&quot;">​</a></h3><p>库仑是电荷量的单位，简称库，符号为 C。1 库仑是指 1 安培电流在 1 秒钟内通过导体横截面的电荷量。</p><p>1库仑 = 6.2415093*10^18元电荷</p><h3 id="电压增大导致电流增大的本质原因" tabindex="-1">电压增大导致电流增大的本质原因 <a class="header-anchor" href="#电压增大导致电流增大的本质原因" aria-label="Permalink to &quot;电压增大导致电流增大的本质原因&quot;">​</a></h3><blockquote><p>那么增加电压，电流增大，到底是单位时间内的电荷速度变快 而电流增加呢？</p><p>还是</p><p>速度不变，是因为更多电荷同时移动呢？</p></blockquote><p>增大电压时，电流增大是因为自由电子的平均定向漂移速度变快，而非更多电荷同时移动。金属中自由电子数量固定，速度提升直接导致单位时间内通过导线横截面的电荷量增加。</p>',9);function d(h,_,p,c,m,u){return a(),t("div",null,[i,r("p",null,[(a(),t("svg",n,s))]),l])}const g=Q(o,[["render",d]]);export{x as __pageData,g as default};
